// the normal loader-id routing. selector 0 is unconditional, 1 means
// manager byte +0x59 is false, 2 means it is true. writeCount and
// writeOffsets/writeValues record the literal manager dword writes
// verified in the branch disassembly (byte offset, value).
// For manager state 0x100, FUN_004308c0 also copies the chosen global
// string into manager +0x40 and sets byte +0x60 to 1; pendingStringVa
// identifies that global string. FUN_004308a0 clears two fields on the
// object at global 0x6c55f8 (offset, access size, literal value).
inline constexpr u32 kCompletionPendingCallVa = 0x4308c0u;
inline constexpr u8 kCompletionPendingStringOffset = 0x40u;
