struct CompletionClearWrite { u16 offset; u8 size; u32 value; };
inline constexpr CompletionClearWrite kCompletionClearWrites[] = {
    {0x178u, 1u, 0x0000u},
    {0x17cu, 4u, 0x0000u},
};
inline constexpr std::size_t kCompletionClearWriteCount =
    sizeof(kCompletionClearWrites) / sizeof(kCompletionClearWrites[0]);

