inline const RecoveredCompletionCutscene* findCompletionCutsceneFlag(u32 flagId) {
    for (const RecoveredCompletionCutscene& row : kRecoveredCompletionCutscenes)
        if (row.rawFlagId == flagId && row.managerState == 0)
            return &row;
    return nullptr;
}

inline const RecoveredCompletionCutscene* findCompletionCutsceneState(
    u32 managerState, bool flag59) {
    const u8 selector = flag59 ? 2u : 1u;
    for (const RecoveredCompletionCutscene& row : kRecoveredCompletionCutscenes) {
        if (row.managerState != managerState) continue;
        if (row.selector == 0 || row.selector == selector) return &row;
    }
    return nullptr;
}

